"use client";

import { cn } from "@/lib/utils";
import {
  CanvasStage,
  ImageFallback,
} from "@/registry/ivan/components/canvas-stage/canvas-stage";
import { centeredFocus } from "@/registry/ivan/lib/image-cover";

import { speedSmearDefaults } from "./speed-smear-material";
import { SpeedSmearScene } from "./speed-smear-scene";
import type { SpeedSmearSceneProps } from "./speed-smear-scene";

export interface SpeedSmearProps extends SpeedSmearSceneProps {
  className?: string;
  label?: string;
}

const defaultLabel =
  "A picture smeared sideways around the pointer, like a head turning fast";

export const SpeedSmear = ({
  className,
  label = defaultLabel,
  src,
  focus = centeredFocus,
  ink = speedSmearDefaults.ink,
  paper = speedSmearDefaults.paper,
  paused = speedSmearDefaults.paused,
  ...sceneProps
}: SpeedSmearProps) => (
  <CanvasStage
    className={cn("touch-pan-y", className)}
    fallback={<ImageFallback focus={focus} src={src} />}
    ground={ink}
    label={label}
    paused={paused}
  >
    {(isAnimating) => (
      <SpeedSmearScene
        {...sceneProps}
        focus={focus}
        ink={ink}
        paper={paper}
        paused={!isAnimating}
        src={src}
      />
    )}
  </CanvasStage>
);

"use client";

import { useFrame, useThree } from "@react-three/fiber";
import { useEffect, useMemo } from "react";
import { MathUtils, PlaneGeometry } from "three";
import type { WebGLRenderer } from "three";

import { usePrintImage } from "@/registry/ivan/hooks/use-print-image";
import type { PrintImage } from "@/registry/ivan/hooks/use-print-image";
import {
  centeredFocus,
  readViewport,
  setCoverImage,
} from "@/registry/ivan/lib/image-cover";
import type { ImageFocus } from "@/registry/ivan/lib/image-cover";
import { PointerLight } from "@/registry/ivan/lib/pointer-light";
import type { PointerSample } from "@/registry/ivan/lib/pointer-trace";

import { SpeedSmearMaterial, speedSmearDefaults } from "./speed-smear-material";

export interface SpeedSmearSceneProps {
  src: string;
  focus?: ImageFocus;
  ink?: string;
  paper?: string;
  smear?: number;
  reach?: number;
  angle?: number;
  cell?: number;
  dither?: boolean;
  paused?: boolean;
}

interface SmearLook {
  ink: string;
  paper: string;
  smear: number;
  reach: number;
  angle: number;
  cell: number;
  dither: boolean;
}

interface SmearFrame {
  delta: number;
  paused: boolean;
  pointer: PointerSample;
}

class SpeedSmearRig {
  readonly material = new SpeedSmearMaterial();
  readonly geometry = new PlaneGeometry(1, 1);
  private readonly light = new PointerLight();
  private cell: number = speedSmearDefaults.cell;

  applyLook({ ink, paper, smear, reach, angle, cell, dither }: SmearLook) {
    const { uniforms } = this.material;
    uniforms.uInk.value.set(ink);
    uniforms.uPaper.value.set(paper);
    uniforms.uSmear.value = smear;
    uniforms.uReach.value = reach;
    uniforms.uAngle.value = MathUtils.degToRad(angle);
    uniforms.uDither.value = dither ? 1 : 0;
    this.cell = cell;
  }

  applyImage(image: PrintImage | null, focus: ImageFocus) {
    setCoverImage(this.material.uniforms, image, focus);
  }

  advance({ delta, paused, pointer }: SmearFrame) {
    this.light.advance(pointer, delta, !paused);
    this.material.uniforms.uKick.value = this.light.kick;
  }

  readonly handleBeforeRender = (renderer: WebGLRenderer) => {
    const { uniforms } = this.material;
    const viewport = readViewport(uniforms, renderer);
    const aspect = viewport.z / Math.max(viewport.w, 1);
    uniforms.uLight.value.set(
      (this.light.x - 0.5) * aspect,
      this.light.y - 0.5
    );
    uniforms.uCell.value = Math.max(
      Math.round(this.cell * renderer.getPixelRatio()),
      1
    );
  };

  dispose() {
    this.material.dispose();
    this.geometry.dispose();
  }
}

export const SpeedSmearScene = ({
  src,
  focus = centeredFocus,
  ink = speedSmearDefaults.ink,
  paper = speedSmearDefaults.paper,
  smear = speedSmearDefaults.smear,
  reach = speedSmearDefaults.reach,
  angle = speedSmearDefaults.angle,
  cell = speedSmearDefaults.cell,
  dither = speedSmearDefaults.dither,
  paused = speedSmearDefaults.paused,
}: SpeedSmearSceneProps) => {
  const invalidate = useThree((state) => state.invalidate);
  const rig = useMemo(() => new SpeedSmearRig(), []);
  const image = usePrintImage(src);

  useEffect(() => () => rig.dispose(), [rig]);

  useEffect(() => {
    rig.applyLook({ angle, cell, dither, ink, paper, reach, smear });
    invalidate();
  }, [angle, cell, dither, ink, invalidate, paper, reach, rig, smear]);

  useEffect(() => {
    rig.applyImage(image, { x: focus.x, y: focus.y });
    invalidate();
  }, [focus.x, focus.y, image, invalidate, rig]);

  useFrame((state, delta) => {
    rig.advance({ delta, paused, pointer: state.pointer });
  });

  return (
    <mesh
      frustumCulled={false}
      geometry={rig.geometry}
      material={rig.material}
      onBeforeRender={rig.handleBeforeRender}
    />
  );
};

import { Color, ShaderMaterial, Vector2 } from "three";
import type { IUniform } from "three";

import {
  createImageCoverUniforms,
  fullscreenVertexShader,
  imageCoverChunk,
} from "@/registry/ivan/lib/image-cover";
import type { ImageCoverUniforms } from "@/registry/ivan/lib/image-cover";
import { bayerChunk, hashChunk } from "@/registry/ivan/lib/print-noise";
import {
  toneChunk,
  toneCurve,
  toneSeparationChunk,
} from "@/registry/ivan/lib/tone-curve";
import type { ToneSeparation } from "@/registry/ivan/lib/tone-curve";

export const speedSmearDefaults = {
  angle: 0,
  cell: 2,
  dither: true,
  ink: "#0B0B0C",
  paper: "#EDECE8",
  paused: false,
  reach: 0.16,
  smear: 0.12,
} as const;

export interface SpeedSmearUniforms extends ImageCoverUniforms {
  uAngle: IUniform<number>;
  uCell: IUniform<number>;
  uDither: IUniform<number>;
  uInk: IUniform<Color>;
  uKick: IUniform<number>;
  uLight: IUniform<Vector2>;
  uPaper: IUniform<Color>;
  uReach: IUniform<number>;
  uSmear: IUniform<number>;
}

const glslFloat = (value: number) => value.toFixed(4);

export const smearSeparation: ToneSeparation = {
  amount: 0.8,
  high: 0.8,
  low: 0.2,
};

const fragmentShader = `
  uniform vec3 uInk;
  uniform vec3 uPaper;
  uniform vec2 uLight;
  uniform float uSmear;
  uniform float uAngle;
  uniform float uReach;
  uniform float uCell;
  uniform float uDither;
  uniform float uKick;

  const float printContrast = ${glslFloat(toneCurve.contrast)};

  ${imageCoverChunk}
  ${hashChunk}
  ${bayerChunk}
  ${toneChunk}

  const int taps = 32;

  ${toneSeparationChunk("crispTone", smearSeparation)}

  void main() {
    if (uHasImage < 0.5) {
      discard;
    }
    float aspect = uResolution.x / uResolution.y;
    vec2 pixel = gl_FragCoord.xy - uOrigin;
    vec2 point = (pixel - uResolution * 0.5) / uResolution.y;
    vec2 along = vec2(cos(uAngle), sin(uAngle));
    vec2 across = vec2(-along.y, along.x);
    vec2 away = point - uLight;
    float reachAlong = dot(away, along) / (uReach * 1.6);
    float reachAcross = dot(away, across) / uReach;
    float mask = exp(-reachAlong * reachAlong - reachAcross * reachAcross);
    float streak = floor(dot(point, across) * uResolution.y / (uCell * 3.0));
    float streakLength = 0.45 + 1.1 * hash(vec2(streak, 3.7));
    float smear = (uSmear + uKick * 0.32) * mask * streakLength;
    float lod = imageLod(uCell);
    float blurLod = lod + clamp(smear * 30.0, 0.0, 2.5);
    float total = 0.0;
    for (int index = 0; index < taps; index++) {
      float offset = float(index) / float(taps - 1) - 0.5;
      vec2 tap = point + along * offset * smear;
      total += imageLuma(coverUv(vec2(tap.x / aspect, tap.y) + 0.5), blurLod);
    }
    float luma = total / float(taps);
    float blurred = imageLuma(coverUv(vec2(point.x / aspect, point.y) + 0.5), blurLod + 2.3);
    luma += (hash(vec2(streak, 9.1)) - 0.5) * 0.14 * mask * min(smear * 12.0, 1.0);
    float tone = crispTone(curveTone(luma, mix(blurred, luma, min(smear * 8.0, 1.0)), printContrast, 1.0));

    float row = floor(dot(point, across) * uResolution.y / uCell);
    float isMiddleRow = step(abs(row - streak * 3.0 - 1.0), 0.5);
    float lineSeed = hash(vec2(streak, 5.3));
    float lineLength = (0.3 + 0.8 * hash(vec2(streak, 7.9))) * smoothstep(0.1, 0.9, uKick);
    float fray = 1.0 - bayer8(pixel / uCell) * 0.45;
    float speedLine = step(0.84, lineSeed) * isMiddleRow * step(abs(reachAlong) / max(lineLength, 0.001), fray) * step(0.3, mask);
    tone = mix(tone, 1.0 - step(0.5, tone), speedLine);

    float ink = 1.0 - tone;
    float printed = step(bayer8(pixel / uCell), ink);
    gl_FragColor = vec4(mix(uPaper, uInk, mix(ink, printed, uDither)), 1.0);
    #include <colorspace_fragment>
  }
`;

const createUniforms = (): SpeedSmearUniforms => ({
  ...createImageCoverUniforms(),
  uAngle: { value: 0 },
  uCell: { value: speedSmearDefaults.cell },
  uDither: { value: 1 },
  uInk: { value: new Color(speedSmearDefaults.ink) },
  uKick: { value: 0 },
  uLight: { value: new Vector2(0, 0) },
  uPaper: { value: new Color(speedSmearDefaults.paper) },
  uReach: { value: speedSmearDefaults.reach },
  uSmear: { value: speedSmearDefaults.smear },
});

export class SpeedSmearMaterial extends ShaderMaterial {
  declare uniforms: SpeedSmearUniforms;

  constructor() {
    super({
      depthTest: false,
      depthWrite: false,
      fragmentShader,
      toneMapped: false,
      uniforms: createUniforms(),
      vertexShader: fullscreenVertexShader,
    });
  }
}

"use client";

import { Canvas } from "@react-three/fiber";
import { useRef } from "react";
import type { ComponentProps, ReactNode } from "react";

import { cn } from "@/lib/utils";
import { useInView } from "@/registry/ivan/hooks/use-in-view";
import { usePrefersReducedMotion } from "@/registry/ivan/hooks/use-prefers-reduced-motion";
import { useWebGLSupport } from "@/registry/ivan/hooks/use-webgl-support";

export interface CanvasStageProps {
  ground: string;
  label: string;
  paused: boolean;
  fallback: ReactNode;
  antialias?: boolean;
  camera?: ComponentProps<typeof Canvas>["camera"];
  className?: string;
  children: (isAnimating: boolean) => ReactNode;
}

interface ImageFallbackProps {
  src: string;
  focus: { x: number; y: number };
}

export const ImageFallback = ({ src, focus }: ImageFallbackProps) => (
  <div
    aria-hidden
    className="absolute inset-0 grayscale"
    style={{
      backgroundImage: `url(${JSON.stringify(src)})`,
      backgroundPosition: `${focus.x * 100}% ${focus.y * 100}%`,
      backgroundSize: "cover",
    }}
  />
);

export const CanvasStage = ({
  ground,
  label,
  paused,
  fallback,
  antialias = false,
  camera,
  className,
  children,
}: CanvasStageProps) => {
  const frame = useRef<HTMLElement>(null);
  const hasWebGL = useWebGLSupport();
  const isInView = useInView(frame);
  const prefersReducedMotion = usePrefersReducedMotion();
  const isAnimating = isInView && !prefersReducedMotion && !paused;

  return (
    <figure
      aria-label={label}
      className={cn(
        "relative m-0 aspect-4/3 w-full overflow-hidden",
        className
      )}
      ref={frame}
      style={{ backgroundColor: ground }}
    >
      {hasWebGL ? (
        <Canvas
          aria-hidden
          camera={camera}
          dpr={[1, 1.75]}
          frameloop={isAnimating ? "always" : "demand"}
          gl={{
            alpha: true,
            antialias,
            powerPreference: "high-performance",
          }}
        >
          {children(isAnimating)}
        </Canvas>
      ) : (
        fallback
      )}
    </figure>
  );
};

import { Vector2, Vector4 } from "three";
import type { IUniform, Texture, WebGLRenderer } from "three";

export interface CoverSource {
  texture: Texture;
  width: number;
  height: number;
}

export interface ImageFocus {
  x: number;
  y: number;
}

export const centeredFocus: ImageFocus = { x: 0.5, y: 0.5 };

export const fullscreenVertexShader = `
  void main() {
    gl_Position = vec4(position.xy * 2.0, 0.0, 1.0);
  }
`;

export const imageCoverChunk = `
  uniform vec2 uOrigin;
  uniform vec2 uResolution;
  uniform sampler2D uImage;
  uniform vec2 uImageSize;
  uniform vec2 uFocus;
  uniform float uHasImage;

  const vec3 lumaWeights = vec3(0.2126, 0.7152, 0.0722);

  vec2 imageSpan() {
    float stageAspect = uResolution.x / uResolution.y;
    float imageAspect = uImageSize.x / uImageSize.y;
    return stageAspect > imageAspect
      ? vec2(1.0, imageAspect / stageAspect)
      : vec2(stageAspect / imageAspect, 1.0);
  }

  vec2 coverUv(vec2 stage) {
    vec2 span = imageSpan();
    vec2 start = clamp(uFocus - span * 0.5, vec2(0.0), vec2(1.0) - span);
    return start + stage * span;
  }

  float imageLuma(vec2 uv, float lod) {
    return dot(textureLod(uImage, uv, lod).rgb, lumaWeights);
  }

  float imageLod(float footprint) {
    float texels = footprint * imageSpan().y * uImageSize.y / uResolution.y;
    return log2(max(texels, 1.0));
  }
`;

export interface ImageCoverUniforms {
  [uniform: string]: IUniform;
  uFocus: IUniform<Vector2>;
  uHasImage: IUniform<number>;
  uImage: IUniform<Texture | null>;
  uImageSize: IUniform<Vector2>;
  uOrigin: IUniform<Vector2>;
  uResolution: IUniform<Vector2>;
}

export const createImageCoverUniforms = (): ImageCoverUniforms => ({
  uFocus: { value: new Vector2(0.5, 0.5) },
  uHasImage: { value: 0 },
  uImage: { value: null },
  uImageSize: { value: new Vector2(1, 1) },
  uOrigin: { value: new Vector2(0, 0) },
  uResolution: { value: new Vector2(1, 1) },
});

export const setCoverImage = (
  uniforms: ImageCoverUniforms,
  image: CoverSource | null,
  focus: ImageFocus
) => {
  uniforms.uImage.value = image?.texture ?? null;
  uniforms.uHasImage.value = image ? 1 : 0;
  uniforms.uImageSize.value.set(image?.width ?? 1, image?.height ?? 1);
  uniforms.uFocus.value.set(focus.x, 1 - focus.y);
};

const viewport = new Vector4();

export const readViewport = (
  uniforms: ImageCoverUniforms,
  renderer: WebGLRenderer
) => {
  renderer.getCurrentViewport(viewport);
  uniforms.uOrigin.value.set(viewport.x, viewport.y);
  uniforms.uResolution.value.set(viewport.z, viewport.w);
  return viewport;
};

export const hashChunk = `
  float hash(vec2 point) {
    return fract(sin(dot(point, vec2(127.1, 311.7))) * 43758.5453);
  }
`;

export const valueNoiseChunk = `
  float valueNoise(vec2 point) {
    vec2 whole = floor(point);
    vec2 part = fract(point);
    vec2 blend = part * part * (3.0 - 2.0 * part);
    return mix(
      mix(hash(whole), hash(whole + vec2(1.0, 0.0)), blend.x),
      mix(hash(whole + vec2(0.0, 1.0)), hash(whole + vec2(1.0, 1.0)), blend.x),
      blend.y
    );
  }
`;

export const bayerChunk = `
  float bayer2(vec2 cell) {
    cell = floor(cell);
    return fract(cell.x / 2.0 + cell.y * cell.y * 0.75);
  }

  float bayer4(vec2 cell) {
    return bayer2(0.5 * cell) * 0.25 + bayer2(cell);
  }

  float bayer8(vec2 cell) {
    return bayer4(0.5 * cell) * 0.25 + bayer2(cell) + 0.5 / 64.0;
  }
`;

export const toneCurve = {
  black: 0.04,
  contrast: 1.35,
  detail: 1.4,
  gamma: 1,
  white: 0.9,
} as const;

const glslFloat = (value: number) => value.toFixed(4);

export const toneChunk = `
  float curveTone(float luma, float blurred, float contrast, float gamma) {
    float sharpened = luma + (luma - blurred) * ${glslFloat(toneCurve.detail)};
    float level = pow(clamp((sharpened - ${glslFloat(toneCurve.black)}) / ${glslFloat(toneCurve.white - toneCurve.black)}, 0.0, 1.0), gamma);
    return clamp((level - 0.5) * contrast + 0.5, 0.0, 1.0);
  }

  vec3 curveColor(vec3 color, vec3 blurred, float contrast, float gamma) {
    return vec3(
      curveTone(color.r, blurred.r, contrast, gamma),
      curveTone(color.g, blurred.g, contrast, gamma),
      curveTone(color.b, blurred.b, contrast, gamma)
    );
  }
`;

export interface ToneSeparation {
  low: number;
  high: number;
  amount: number;
}

export const printSeparation: ToneSeparation = {
  amount: 0.55,
  high: 0.84,
  low: 0.16,
};

export const toneSeparationChunk = (
  name: string,
  { low, high, amount }: ToneSeparation
) => `
  float ${name}(float tone) {
    return mix(tone, smoothstep(${glslFloat(low)}, ${glslFloat(high)}, tone), ${glslFloat(amount)});
  }
`;

export interface PointerSample {
  x: number;
  y: number;
}

const holdAfterMove = 2.5;
const movedBy = 0.0001;

export class PointerTrace {
  x = 0.5;
  y = 0.5;
  isActive = false;
  private hasMoved = false;
  private idle = 0;

  update({ x, y }: PointerSample, step: number, isAnimating: boolean) {
    const nextX = (x + 1) / 2;
    const nextY = (y + 1) / 2;
    if (Math.abs(nextX - this.x) + Math.abs(nextY - this.y) > movedBy) {
      this.hasMoved = true;
      this.idle = 0;
    } else {
      this.idle += step;
    }
    this.x = nextX;
    this.y = nextY;
    this.isActive =
      this.hasMoved && (!isAnimating || this.idle < holdAfterMove);
  }
}

import { PointerTrace } from "@/registry/ivan/lib/pointer-trace";
import type { PointerSample } from "@/registry/ivan/lib/pointer-trace";

const followRate = 9;
const maxStep = 0.05;
const minStep = 0.001;

export const restingLight = { x: 0.24, y: 0.78 } as const;

export class PointerLight {
  readonly trace = new PointerTrace();
  x: number = restingLight.x;
  y: number = restingLight.y;
  kick = 0;
  private clock = 0;

  advance(pointer: PointerSample, delta: number, isAnimating: boolean) {
    const step = Math.min(delta, maxStep);
    const { trace } = this;
    trace.update(pointer, step, isAnimating);
    if (isAnimating) {
      this.clock += step;
    }
    const wanderX = 0.5 + Math.sin(this.clock * 0.4 - 1.3) * 0.32;
    const wanderY = 0.62 + Math.cos(this.clock * 0.31) * 0.2;
    let targetX = trace.isActive ? trace.x : wanderX;
    let targetY = trace.isActive ? trace.y : wanderY;
    if (!(isAnimating || trace.isActive)) {
      targetX = restingLight.x;
      targetY = restingLight.y;
    }
    const blend = isAnimating ? 1 - Math.exp(-step * followRate) : 1;
    const previousX = this.x;
    const previousY = this.y;
    this.x += (targetX - this.x) * blend;
    this.y += (targetY - this.y) * blend;
    const velocity =
      Math.hypot(this.x - previousX, this.y - previousY) /
      Math.max(step, minStep);
    const wanted = isAnimating ? Math.min(velocity / 2.5, 1) : 0;
    const rate = wanted > this.kick ? 14 : 3;
    this.kick += (wanted - this.kick) * (1 - Math.exp(-rate * step));
  }
}

"use client";

import { useSyncExternalStore } from "react";

const reducedMotionQuery = "(prefers-reduced-motion: reduce)";

const subscribe = (onChange: () => void) => {
  const mediaQuery = window.matchMedia(reducedMotionQuery);
  mediaQuery.addEventListener("change", onChange);
  return () => mediaQuery.removeEventListener("change", onChange);
};

const getSnapshot = () => window.matchMedia(reducedMotionQuery).matches;

const getServerSnapshot = () => false;

export const usePrefersReducedMotion = () =>
  useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);

"use client";

import { useSyncExternalStore } from "react";

let cachedSupport: boolean | null = null;

const detectWebGL = () => {
  if (cachedSupport !== null) {
    return cachedSupport;
  }
  try {
    const probe = document.createElement("canvas");
    const context = probe.getContext("webgl2") ?? probe.getContext("webgl");
    context?.getExtension("WEBGL_lose_context")?.loseContext();
    cachedSupport = context !== null;
  } catch {
    cachedSupport = false;
  }
  return cachedSupport;
};

const subscribe = (onChange: () => void) => {
  window.addEventListener("pageshow", onChange);
  return () => window.removeEventListener("pageshow", onChange);
};

const getServerSnapshot = () => true;

export const useWebGLSupport = () =>
  useSyncExternalStore(subscribe, detectWebGL, getServerSnapshot);

"use client";

import { useEffect, useState } from "react";
import type { RefObject } from "react";

export const useInView = (
  target: RefObject<Element | null>,
  rootMargin = "10% 0px"
) => {
  const [isInView, setIsInView] = useState(false);

  useEffect(() => {
    const element = target.current;
    if (!element) {
      return;
    }
    const observer = new IntersectionObserver(
      ([entry]) => setIsInView(entry?.isIntersecting ?? false),
      { rootMargin }
    );
    observer.observe(element);
    return () => observer.disconnect();
  }, [rootMargin, target]);

  return isInView;
};

"use client";

import { useThree } from "@react-three/fiber";
import { useEffect, useState } from "react";
import { LinearMipmapLinearFilter, TextureLoader } from "three";
import type { Texture } from "three";

export interface PrintImage {
  texture: Texture;
  element: HTMLImageElement;
  width: number;
  height: number;
}

interface LoadedImage {
  src: string;
  image: PrintImage;
}

const loadTexture = async (src: string) => {
  const loader = new TextureLoader();
  loader.setCrossOrigin("anonymous");
  try {
    return await loader.loadAsync(src);
  } catch {
    return null;
  }
};

export const usePrintImage = (src: string): PrintImage | null => {
  const invalidate = useThree((state) => state.invalidate);
  const [loaded, setLoaded] = useState<LoadedImage | null>(null);

  useEffect(() => {
    let isCurrent = true;
    let texture: Texture | null = null;
    const load = async () => {
      const value = await loadTexture(src);
      if (!value) {
        return;
      }
      if (!isCurrent) {
        value.dispose();
        return;
      }
      value.generateMipmaps = true;
      value.minFilter = LinearMipmapLinearFilter;
      texture = value;
      const element: HTMLImageElement = value.image;
      setLoaded({
        image: {
          element,
          height: element.naturalHeight,
          texture: value,
          width: element.naturalWidth,
        },
        src,
      });
      invalidate();
    };
    void load();
    return () => {
      isCurrent = false;
      texture?.dispose();
    };
  }, [invalidate, src]);

  return loaded && loaded.src === src ? loaded.image : null;
};
